#include <bits/stdc++.h>
#define fst first
#define snd second
#define fore(i,a,b) for(int i=a,ThxDem=b;i<ThxDem;++i)
#define pb push_back
#define ALL(s) s.begin(),s.end()
#define FIN ios_base::sync_with_stdio(0);cin.tie(0);cout.tie(0)
#define SZ(s) int(s.size())
using namespace std;
typedef long long ll;
typedef pair<int,int> ii;

const int INF=1e9;
struct FlowNetwork {
	int n, m, k, t;
	vector<int> u,v,dist,curFlow,pre,preEdge,prevNode,potential;
	struct Edge {
		int to, flow, capacity, cost, rev;
	};
	vector<vector<Edge>> adj;
	FlowNetwork(int n):n(n),u(n),v(n),dist(n),curFlow(n),pre(n),preEdge(n),prevNode(n),potential(n),adj(n){}
	void addEdge(int s, int t, int cap, int cst) {
		Edge a = {t, 0, cap, cst, (int)adj[t].size()};
		Edge b = {s, 0, 0, -cst, (int)adj[s].size()};
		adj[s].push_back(a);
		adj[t].push_back(b);
	}
	pair<int,int> getMinCostMaxFlow(int s, int t) {
		int totalFlow=0, totalCost=0;
		while(true) {
			fill(ALL(dist), INT_MAX);
			priority_queue<pair<int,int>, vector<pair<int,int>>, greater<pair<int,int>>> pq;
			pq.push({0,s});
			dist[s]=0;
			curFlow[s]=INT_MAX;
			while(!pq.empty()) {
				auto [d, u]=pq.top(); pq.pop();
				if(d!=dist[u]) continue;
				for(int i=0; i<(int)adj[u].size(); ++i) {
					auto &e=adj[u][i];
					int v=e.to;
					if(e.flow>=e.capacity) continue;
					int newDist=dist[u]+e.cost+potential[u]-potential[v];
					if(dist[v]>newDist) {
						dist[v]=newDist;
						pq.push({newDist,v});
						prevNode[v]=u;
						preEdge[v]=i;
						curFlow[v]=min(curFlow[u], e.capacity - e.flow);
					}
				}
			}
			if(dist[t]==INT_MAX) break;
			for(int i=0; i<n; ++i) potential[i]+=dist[i];
			int df=curFlow[t];
			for(int v=t; v!=s; v=prevNode[v]) {
				auto &e=adj[prevNode[v]][preEdge[v]];
				e.flow+=df;
				adj[v][e.rev].flow-=df;
				totalCost+=df*e.cost;
			}
			totalFlow+=df;
		}
		return {totalFlow, totalCost};
	}
};

int n,m,k,c,d;

int main() {
	int x,y;
	scanf("%d%d%d%d%d",&n,&m,&k,&c,&d);
	FlowNetwork network(6+107*n);
	fore(_,0,k){
		scanf("%d",&x); x--;
		network.addEdge(0,1+x,1,0);
	}
	fore(_,0,m){
		scanf("%d%d",&x,&y); x--; y--;
		fore(i,0,105){
			fore(j,0,51){
				network.addEdge(1+i*n+x,1+(i+1)*n+y,1,c+d*(2*j+1));
				network.addEdge(1+i*n+y,1+(i+1)*n+x,1,c+d*(2*j+1));
			}
		}
	}
	fore(i,0,105)fore(j,0,n) network.addEdge(1+i*n+j,1+(i+1)*n+j,51,c);
	fore(i,0,105) network.addEdge(1+i*n,1+105*n,51,0);
	auto [f, cost]=network.getMinCostMaxFlow(0,1+105*n);
	printf("%d\n",cost);
	return 0;
}
